(async () => {
  const names = [["mp4-h264-high-aac.mp4", "video"], ["mp4-h264-aac-start1500.mp4", "video"], ["mp4-h264-aac-fragmented.mp4", "video"], ["mp4-h264-aac-bframes-no-edit-list.mp4", "video"], ["mp4-opus.mp4", "audio"], ["mp4-h264-video-only.mp4", "video"]];
  const rows = [];
  for (const [name, tag] of names) {
