    m.preload = 'auto';
    m.muted = true;
    document.body.appendChild(m);
    const loaded = once(m, 'loadedmetadata', 3000);
    m.src = name;
    const how = await loaded;
    const atMeta = 'ct=' + r2(m.currentTime) + ' dur=' + r2(m.duration) + ' seek=' + rng(m.seekable);
