    rows.push([name, how, 'rs=' + m.readyState, 'ns=' + m.networkState, atMeta, 'later ct=' + r2(m.currentTime) + ' dur=' + r2(m.duration) + ' seek=' + rng(m.seekable) + ' buf=' + rng(m.buffered), m.error ? 'err=' + m.error.code : '']);
    m.remove();
  }
  return rows;
})()

(async () => {
  const names = [["mp4-h264-high-aac.mp4", "video"], ["mp4-h264-baseline-aac.mp4", "video"], ["mp4-h264-high-aac-moov-at-end.mp4", "video"], ["m4a-aac.m4a", "audio"], ["webm-vp8-vorbis.webm", "video"], ["webm-vp9-opus.webm", "video"], ["ogg-vorbis.ogg", "audio"], ["ogg-opus.opus", "audio"], ["ogg-flac.oga", "audio"], ["mp3.mp3", "audio"], ["flac.flac", "audio"], ["wav-pcm-s16.wav", "audio"], ["aac-adts.aac", "audio"], ["mp4-h264-video-only.mp4", "video"], ["webm-vp8-video-only.webm", "video"], ["webm-vp8-321x241.webm", "video"], ["webm-vp9-321x241.webm", "video"], ["mp4-h264-bt709.mp4", "video"], ["mp4-h264-bt601.mp4", "video"], ["mp4-h264-untagged-bt709.mp4", "video"], ["mp4-h264-fullrange-bt709.mp4", "video"], ["webm-vp8-vorbis-start1500.webm", "video"], ["mp4-h264-aac-start1500.mp4", "video"]];
  const rows = [];
  for (const [name, tag] of names) {
    const m = document.createElement(tag);
    m.muted = true;
    document.body.appendChild(m);
    m.src = name;
    const t0 = performance.now();
